def legacy_types_to_categories(apps, schema_editor):
    """Existing products keep their section: every old fixed type in use becomes a real category."""
    Category = apps.get_model("management", "Category")
    Item = apps.get_model("management", "Item")
    for code, (name, emoji, order) in LEGACY.items():
        items = Item.objects.filter(drink_type=code, category__isnull=True)
        if items.exists():
            cat = Category.objects.create(name=name, emoji=emoji, sort_order=order)
            items.update(category=cat)


